(function(){document.addEventListener("submit",function(e){if(!e.defaultPrevented){var u=e.target;if(u.getAttribute("data-no-double-guard")===null){var t=u.querySelector('button[type="submit"]');if(t){if(t.getAttribute("data-submitting")==="1"){e.preventDefault();return}t.setAttribute("data-submitting","1"),t.style.opacity="0.6",setTimeout(function(){t.removeAttribute("data-submitting"),t.style.opacity=""},4e3)}}}})})();
